import numpy as np
t=df['t'].values;P=df['P'].values;y=df['dP_dt'].values
# fit y against polynomial basis in P (0..4) and t (0..2) with cross terms; check residual
def fit(cols,names):
    A=np.column_stack(cols)
    c,res,_,_=np.linalg.lstsq(A,y,rcond=None)
    r=y-A@c
    print(len(cols), 'NMSE',np.var(r)/np.var(y))
    return c
